 PM I was told maintenance is trying to locate the pendant.  The aid only has status of where it was last pushed which was last night in her room.\r\n4:40 pm I came back from a walk and met with Julian.  I was able to get Mom to eat probably 10 sips of soup, 1/2 cup of coffee, and water and juice.  She also took about 500mg of tylenol.  We'll see how if that helps her feel better.\r\nOn the Duffy note, Corrine is here and trying get Duffy to eat some of his medicine.\r\n5:15 PM Maintenance was able to get Mom a new pendant, and we are waiting on a new post office key.\r\n9:00 PM Mom went to sleep but was a bit more agitated this evening and still feeling a lot of pain.  I'll talk to Doctor Gabriel tomorrow to see what we can do about this.  And Duffy ate the sedative a couple hours ago, heartening news on the matting issue.\r\n\r\n	0.00	11	
