231	2025-01-12 23:42:11.323682-05	2025-01-12 16:00:00-05	2025-01-12 18:30:00-05	2.50	f	14	92	Continued working on Documentation form.  I add the url to include parent_id for the createview that selects the model in the parent select.  If the parent is selected then the select widget is disabled in the form.  I did this by adding an __init__ method in the mixin class that the Documentation forms inherit.class DocFormInitMixin():\r\n    def __init__(self, *args, **kwargs):\r\n        super().__init__(*args, **kwargs)\r\n        if 'parent' in self.initial:\r\n            self.fields['parent'].disabled = True\r\n\r\n\r\nclass ItemDocumentationForm(DocFormInitMixin, forms.ModelForm):\r\n    class Meta:\r\n        model = ItemDocumentation\r\n        fields = ['parent', 'file', 'description']\r\n\r\n\r\nclass TimesheetEntryDocumentationForm(DocFormInitMixin, forms.ModelForm):\r\n    class Meta:\r\n        model = TimesheetEntryDocumentation\r\n        fields = ['parent', 'file', 'description']\r\n\r\nWhen the form is submitted, disabled is set to false via jquery on all the elements with class 'select'.\r\nI was also able to get existing documentation listed on the form.	0.00	3	
