333	2025-04-07 17:09:37.205387-04	2025-04-07 08:00:00-04	2025-04-07 10:15:00-04	2.25	f	14	95	Got the input and output stacks working. I discovered you cannot share I2C addresses between input and output boards.\r\nAddress 0: INPUT board 1 (bottom)\r\nAddress 1: INPUT board 2 (2nd from bottom)\r\nAddress 2: INPUT board 3 (3rd from bottom)\r\nAddress 3: OUTPUT board 1(4th from bottom)\r\nAddress 4: OUTPUT board 2(5th from bottom)\r\n\r\nOutput Board:\r\nHowever the board output board that does not have a working power LED does not have an LED for channel 1.   However the channel works.\r\nI tested the outputs with 5V and 24V and ran through all the channels via python script.\r\nThe common is the voltage you want to switch on the output channels.\r\n\r\nInput Boards:\r\nThe common needs to be connected to the ground of the signal source, thus the opto isolation. \r\n\r\nSo far I tested the output of channel 1 of board(4), this is the one that has defective led on channel 1, onto input of channel 1 on input board(2) and it works.\r\n\r\nI'll be working on the Input Output Building Automation board next.	80.00	1	
