358	2025-04-30 02:40:15.789254-04	2025-04-29 16:00:00-04	2025-04-29 19:30:00-04	3.50	f	14	95	Wrote to Ami and Udi about the linear servo, AD card with photodiodes, and temperature limits for the thermistors.  The ones I bought should work for our purposes.  I'm going to integrate one of the 24 volt motors to make sure the camera tilt pan motor controller work for our application.  After that I will get final approval on order for rest of the parts.\r\nI also finished worked on the drawings for the linear servo.  We will be using pin 12 for the PWM for the control of the linear servo.\r\nI found python example code for the producing the pulse for the actuator.import RPi.GPIO as GPIO\r\nimport time\r\n\r\n# Configure GPIO pin (replace with your desired pin)\r\npwm_pin = 18\r\nGPIO.setmode(GPIO.BCM)\r\nGPIO.setup(pwm_pin, GPIO.OUT)\r\n\r\n# Set PWM frequency (example: 8000 Hz)\r\npwm_frequency = 8000\r\npwm = GPIO.PWM(pwm_pin, pwm_frequency)\r\n\r\n# Calculate and set the duty cycle (example: 9.52%)\r\npulse_width = 1190  # us\r\nperiod = 1/pwm_frequency  # seconds\r\nduty_cycle = (pulse_width / (period * 1000000)) * 100\r\npwm.start(duty_cycle)\r\n\r\n# Wait for a while to see the pulse\r\ntime.sleep(1)\r\n\r\n# Stop PWM output\r\npwm.stop()\r\nGPIO.cleanup()	80.00	1	
