434	2025-06-27 16:20:58.020888-04	2025-06-27 08:30:00-04	2025-06-27 09:15:00-04	0.75	f	14	97	donnnican was not able to get to her timesheets.  Her timesheetuser had gotten deleted.  I created another timesheetuser but that didn't work.  The problem was that we needed to create a usertimesheetperiod object for her.  I did  this through manage.py shell.\r\nI created a new usertimesheetperiod assigned her timesheetuser as the user.  Then located the timesheetperiod and assigned the period to this and saved.  You can't use the admin page because it does not allow for nulls or blanks for date_started or date_finished.  I can change this in the future.\r\n\r\nIn [1]: from timesheets.models import UserTimesheetPeriod\r\nIn [2]: from employee.models import TimesheetUser\r\nIn [3]: from django.contrib.auth.models import User\r\nIn [5]: user = User.objects.get(username='donnnican')\r\nIn [6]: tsuser = TimesheetUser.objects.get(user=user)\r\nIn [7]: tsuser.user.username\r\nOut[7]: 'donnnican'\r\nIn [8]: utp = UserTimesheetPeriod()\r\nIn [9]: utp.user = tsuser\r\nIn [10]: from timesheets.models import TimesheetPeriod\r\nIn [11]: tsp = TimesheetPeriod.objects.last()\r\nIn [12]: tsp.date_start\r\nOut[12]: datetime.datetime(2025, 6, 22, 5, 0, tzinfo=datetime.timezone.utc)    \r\nIn [14]: utp.period=tsp\r\nIn [15]: utp.save()\r\nIn [16]: exit	0.00	7	
